CREATE TABLE guild_settings(guild TEXT PRIMARY KEY, settings TEXT NOT NULL DEFAULT '{}');
CREATE TABLE module_settings(guild TEXT NOT NULL REFERENCES guild_settings ON DELETE CASCADE, name TEXT NOT NULL, enabled INTEGER NOT NULL, PRIMARY KEY(guild,name));
CREATE TABLE configured_roles(guild TEXT NOT NULL REFERENCES guild_settings, key TEXT NOT NULL, id TEXT NOT NULL, PRIMARY KEY(guild,key));
CREATE TABLE configured_channels(guild TEXT NOT NULL REFERENCES guild_settings, key TEXT NOT NULL, id TEXT NOT NULL, PRIMARY KEY(guild,key));
CREATE TABLE ticket_types(guild TEXT NOT NULL REFERENCES guild_settings, key TEXT NOT NULL, config TEXT NOT NULL, PRIMARY KEY(guild,key));
CREATE TABLE tickets(id INTEGER PRIMARY KEY AUTOINCREMENT,guild TEXT NOT NULL REFERENCES guild_settings, type TEXT NOT NULL, author TEXT NOT NULL, channel TEXT UNIQUE, panel TEXT, state TEXT NOT NULL, priority TEXT NOT NULL, assignee TEXT, created INTEGER NOT NULL, updated INTEGER NOT NULL, first_response INTEGER, closed INTEGER, closer TEXT, reason TEXT, policy TEXT NOT NULL, answers TEXT NOT NULL, transcript TEXT, operation TEXT);
CREATE INDEX ticket_list ON tickets(guild,state,id);
CREATE INDEX ticket_author ON tickets(guild,author,type,created);
CREATE TABLE ticket_participants(ticket INTEGER REFERENCES tickets ON DELETE CASCADE,user TEXT NOT NULL,PRIMARY KEY(ticket,user));
CREATE TABLE applications(ticket INTEGER PRIMARY KEY REFERENCES tickets ON DELETE CASCADE, guild TEXT NOT NULL,status TEXT NOT NULL,reviewer TEXT,details TEXT NOT NULL DEFAULT '{}');
CREATE TABLE application_history(id INTEGER PRIMARY KEY,ticket INTEGER NOT NULL REFERENCES tickets ON DELETE CASCADE, actor TEXT NOT NULL,status TEXT NOT NULL,detail TEXT NOT NULL,time INTEGER NOT NULL);
CREATE TABLE tier_definitions(guild TEXT NOT NULL REFERENCES guild_settings,key TEXT NOT NULL,config TEXT NOT NULL,PRIMARY KEY(guild,key));
CREATE TABLE tier_applications(ticket INTEGER PRIMARY KEY REFERENCES tickets ON DELETE CASCADE,tier TEXT NOT NULL);
CREATE TABLE family_members(guild TEXT NOT NULL REFERENCES guild_settings,user TEXT NOT NULL,static TEXT NOT NULL,nick TEXT NOT NULL,rank TEXT NOT NULL,tier TEXT,joined INTEGER NOT NULL,accepted TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(guild,user), UNIQUE(guild,static));
CREATE INDEX family_nick ON family_members(guild,nick COLLATE NOCASE);
CREATE TABLE member_history(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,user TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL,time INTEGER NOT NULL);
CREATE INDEX family_history ON member_history(guild,user,id);
CREATE TABLE reports(ticket INTEGER PRIMARY KEY REFERENCES tickets ON DELETE CASCADE,target TEXT NOT NULL,context TEXT NOT NULL,decision TEXT);
CREATE TABLE strikes(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,user TEXT NOT NULL,kind TEXT NOT NULL,reason TEXT NOT NULL,evidence TEXT,actor TEXT NOT NULL,created INTEGER NOT NULL,expires INTEGER,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE moderation_cases(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,user TEXT NOT NULL,action TEXT NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE blacklisted_members(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,kind TEXT NOT NULL,value TEXT NOT NULL COLLATE NOCASE,reason TEXT NOT NULL,evidence TEXT,actor TEXT NOT NULL,created INTEGER NOT NULL,expires INTEGER,active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX blacklist_lookup ON blacklisted_members(guild,kind,value,active);
CREATE TABLE events(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,title TEXT NOT NULL,details TEXT NOT NULL,start INTEGER NOT NULL,capacity INTEGER NOT NULL,state TEXT NOT NULL,organizer TEXT NOT NULL,channel TEXT,message TEXT);
CREATE TABLE event_attendance(event INTEGER NOT NULL REFERENCES events ON DELETE CASCADE,user TEXT NOT NULL,status TEXT NOT NULL,confirmed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(event,user));
CREATE TABLE voice_sessions(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,user TEXT NOT NULL,started INTEGER NOT NULL,last_seen INTEGER NOT NULL,ended INTEGER);
CREATE UNIQUE INDEX voice_active ON voice_sessions(guild,user) WHERE ended IS NULL;
CREATE TABLE karma_points(guild TEXT NOT NULL,user TEXT NOT NULL,points INTEGER NOT NULL CHECK(points>=0),PRIMARY KEY(guild,user));
CREATE TABLE point_transactions(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,user TEXT NOT NULL,delta INTEGER NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL,time INTEGER NOT NULL,source TEXT UNIQUE);
CREATE INDEX points_week ON point_transactions(guild,time,user);
CREATE TABLE achievements(guild TEXT NOT NULL,user TEXT NOT NULL,name TEXT NOT NULL,time INTEGER NOT NULL,PRIMARY KEY(guild,user,name));
CREATE TABLE giveaways(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,title TEXT NOT NULL,config TEXT NOT NULL,organizer TEXT NOT NULL,ends INTEGER NOT NULL,state TEXT NOT NULL,channel TEXT,message TEXT,result TEXT);
CREATE TABLE polls(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,title TEXT NOT NULL,config TEXT NOT NULL,ends INTEGER NOT NULL,state TEXT NOT NULL,channel TEXT,message TEXT);
CREATE TABLE suggestions(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,author TEXT NOT NULL,body TEXT NOT NULL,state TEXT NOT NULL,comment TEXT,channel TEXT,message TEXT);
CREATE TABLE ballots(kind TEXT NOT NULL,object INTEGER NOT NULL,user TEXT NOT NULL,choice TEXT NOT NULL,PRIMARY KEY(kind,object,user));
CREATE TABLE embed_templates(guild TEXT NOT NULL,name TEXT NOT NULL,config TEXT NOT NULL,PRIMARY KEY(guild,name));
CREATE TABLE scheduled_tasks(key TEXT PRIMARY KEY,guild TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,due INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'pending');
CREATE INDEX due_tasks ON scheduled_tasks(state,due);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY,guild TEXT NOT NULL,action TEXT NOT NULL,actor TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL,time INTEGER NOT NULL);
CREATE INDEX audit_page ON audit_logs(guild,id);
CREATE TABLE drafts(id TEXT PRIMARY KEY,guild TEXT NOT NULL,user TEXT NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX drafts_expiry ON drafts(expires);
CREATE TABLE cooldowns(guild TEXT NOT NULL,user TEXT NOT NULL,key TEXT NOT NULL,until INTEGER NOT NULL,PRIMARY KEY(guild,user,key));
